    "Subcommands": [
      {
        "Name": "publish",
        "Description": "Publish a solution package (.zip) to the UiPath solution feed. The .zip must be produced by 'solution pack'. By default the package lands in the tenant feed; use --personal-workspace to target the current user's Personal Workspace feed. After publishing, use 'solution deploy run' to deploy it."
      },
      {
        "Name": "pack",
        "Description": "Pack a UiPath solution into a deployable .zip package. Accepts a solution directory (containing .uipx) or a .uis file. Output is used with 'solution publish' to upload to UiPath. Pass --dry-run to check that the solution packs without producing a package."
      },
      {
        "Name": "cleanup",
        "Description": "Remove unused items from every project in a UiPath solution. Accepts a solution directory (containing .uipx) or a .uis file. For a directory the project sources are modified in place. Pass --dry-run to only detect unused items."
      },
      {
        "Name": "restore",
        "Description": "Restore NuGet dependencies for every project in a UiPath solution using the authenticated session. Accepts a solution directory (containing .uipx) or a .uis file. Resolves dependencies in place and does not produce a package — run it before 'uip solution pack'."
      },
      {
        "Name": "download",
        "Description": "Download/export a solution from Studio Web"
      },
      {
        "Name": "init",
        "Description": "Initialize a new empty UiPath solution. Creates a directory named after the solution containing a .uipx manifest file with an empty Projects array, plus AGENTS.md and CLAUDE.md briefing files that orient AI coding agents to the solution. Use 'solution projects add' to add projects afterward."
      },
      {
        "Name": "projects",
        "Description": "Manage projects within a UiPath solution (.uipx). Add, import, list, or remove the automation projects registered in the solution manifest — RPA processes, tests, agents, Maestro flows, case and BPMN projects, coded apps, functions, API workflows, and other buildable project types. A library is not a project: publish it on its own, then attach it with 'uip solution resources add --source remote --kind Library --name <library-name>'."
      },
      {
        "Name": "packages",
        "Description": "Solution packages — packaged solution bundles published to UiPath for deployment. Use 'packages list' to find available packages for 'deploy run'."
      },
      {
        "Name": "deploy",
        "Description": "Deploy, activate, uninstall, and monitor solution deployments. Typical workflow: run -> check status -> (optionally) activate -> uninstall."
      },
      {
        "Name": "upload",
        "Description": "Upload a solution to UiPath Studio Web for browser-based editing. Accepts a solution directory, .uipx file, or .uis file. The command probes Studio Web for the bundled SolutionId: if the cloud solution does not exist it is imported as new; if it already exists the upload is refused unless --force is passed. Forcing replaces the cloud project in place and wipes its Studio Web version history."
      },
      {
        "Name": "resources",
        "Description": "Manage solution resources. Resources are the queues, assets, buckets, processes, connections, entities, choice sets, and other Orchestrator and Data Service objects that projects depend on."
      },
      {
        "Name": "delete",
        "Description": "Delete a solution from Studio Web by its solution ID. The ID is emitted by 'solution upload' and 'flow debug' in their output."
      },
      {
        "Name": "feeds",
        "Description": "Solution feeds (publish locations) — the tenant feed, your Personal Workspace, and folder feeds. Use 'feeds list' to find a feed's name or key for 'publish --feed'."
